INSERT INTO `bai_viet` (`id`, `tieude`, `anhien`, `noidung`, `hinh_anh`, `danhmuc_baiviet_id`, `user_id`, `created_at`, `updated_at`) VALUES
('bd8b0839-b613-11f0-83be-089798d71904', 'Nghệ thuật phối màu nội thất phòng khách hiện đại', 1, 'Phòng khách là không gian trung tâm thể hiện cá tính của gia chủ. Khi lựa chọn màu sắc, nên ưu tiên tông trung tính như be, xám hoặc trắng kết hợp với các điểm nhấn đậm màu như cam đất hoặc xanh rêu. Sự cân bằng giữa sáng và tối giúp không gian vừa sang trọng vừa ấm áp. Ngoài ra, việc kết hợp vật liệu tự nhiên như gỗ, mây tre hoặc đá sẽ tạo cảm giác gần gũi và thư giãn. Đừng quên sử dụng thảm, rèm cửa và gối ôm để tăng thêm chiều sâu cho tổng thể thiết kế.', 'https://images.pexels.com/photos/1571460/pexels-photo-1571460.jpeg', 'bd84bc1a-b613-11f0-83be-089798d71904', NULL, '2025-10-31 11:40:34', '2025-10-31 11:40:34'),
('bd8b3f22-b613-11f0-83be-089798d71904', 'Bí quyết chọn sofa phù hợp với không gian sống', 1, 'Sofa là linh hồn của phòng khách, vì vậy lựa chọn đúng kiểu dáng, màu sắc và chất liệu là yếu tố quyết định. Với phòng nhỏ, nên chọn sofa góc chữ L để tiết kiệm diện tích, còn với không gian lớn, sofa da thật hoặc sofa vải nỉ cao cấp mang lại vẻ sang trọng. Màu sắc nên hài hòa với tường và sàn nhà, đồng thời có thể tạo điểm nhấn bằng gối tựa hoặc thảm. Ngoài ra, chất liệu da thật giúp dễ vệ sinh, trong khi vải nỉ đem lại cảm giác mềm mại, phù hợp với khí hậu mát mẻ.', 'https://images.pexels.com/photos/276528/pexels-photo-276528.jpeg', 'bd84bbda-b613-11f0-83be-089798d71904', NULL, '2025-10-31 11:40:34', '2025-10-31 11:40:34'),
('bd8b4173-b613-11f0-83be-089798d71904', 'Thiết kế phòng ăn mở – xu hướng nội thất năm 2025', 1, 'Không gian mở giữa phòng bếp và phòng ăn đang trở thành xu hướng phổ biến. Việc loại bỏ vách ngăn giúp ánh sáng lan tỏa, tạo cảm giác rộng rãi và kết nối giữa các thành viên. Bàn ăn gỗ sồi kết hợp ghế bọc da hoặc nỉ mang lại vẻ sang trọng nhưng vẫn thân thiện. Đèn thả trần với ánh sáng vàng ấm giúp bữa ăn thêm ấm cúng. Đừng quên bố trí thêm cây xanh nhỏ hoặc tranh tường để tạo điểm nhấn nhẹ nhàng, giúp không gian sống sinh động và thoáng đãng hơn.', 'https://images.pexels.com/photos/4207785/pexels-photo-4207785.jpeg', 'bd849f7c-b613-11f0-83be-089798d71904', NULL, '2025-10-31 11:40:34', '2025-10-31 11:40:34'),
('bd8b434f-b613-11f0-83be-089798d71904', 'Ánh sáng và cảm xúc trong thiết kế nội thất', 1, 'Ánh sáng đóng vai trò quan trọng trong việc tạo cảm xúc cho không gian sống. Việc kết hợp ánh sáng tự nhiên và nhân tạo hợp lý có thể thay đổi hoàn toàn không khí của căn phòng. Ban ngày, tận dụng tối đa nguồn sáng tự nhiên qua cửa sổ lớn hoặc rèm mỏng. Buổi tối, sử dụng đèn sàn, đèn bàn hoặc đèn âm trần với nhiệt độ màu ấm để tạo cảm giác thư giãn. Ngoài ra, ánh sáng gián tiếp từ các khe hắt trần hoặc tường có thể giúp căn phòng trở nên sang trọng và sâu hơn.', 'https://images.pexels.com/photos/6585757/pexels-photo-6585757.jpeg', 'bd84bc1a-b613-11f0-83be-089798d71904', 'bd05b6d0-b613-11f0-83be-089798d71904', '2025-10-31 11:40:34', '2025-10-31 11:40:34'),
('bd8b44bd-b613-11f0-83be-089798d71904', 'Không gian làm việc tại nhà tiện nghi và sáng tạo', 1, 'Xu hướng làm việc tại nhà khiến nhu cầu về góc làm việc cá nhân tăng cao. Một bàn làm việc đơn giản, ghế công thái học và ánh sáng tốt sẽ giúp nâng cao hiệu suất. Màu sắc nhẹ nhàng như xanh pastel, trắng hoặc gỗ sáng giúp tập trung hơn. Nếu có thể, đặt bàn gần cửa sổ để tận dụng ánh sáng tự nhiên. Trang trí thêm kệ sách, cây nhỏ hoặc tranh nghệ thuật để tạo động lực mỗi khi làm việc. Sự hài hòa giữa công năng và thẩm mỹ là yếu tố then chốt của không gian này.', 'https://images.pexels.com/photos/813691/pexels-photo-813691.jpeg', 'bd849f7c-b613-11f0-83be-089798d71904', NULL, '2025-10-31 11:40:34', '2025-10-31 11:40:34'),
('bd8b4632-b613-11f0-83be-089798d71904', 'Phong thủy phòng ngủ – Bí quyết ngủ ngon mỗi đêm', 1, 'Phòng ngủ là nơi tái tạo năng lượng nên việc bố trí hợp phong thủy rất quan trọng. Giường không nên đặt đối diện cửa chính hoặc gương, tránh luồng khí xấu. Màu sắc nên chọn các gam ấm như kem, be, hồng nhạt hoặc xanh nhẹ để mang lại cảm giác an yên. Vật liệu tự nhiên như gỗ, vải cotton giúp giấc ngủ sâu hơn. Tránh để quá nhiều thiết bị điện tử trong phòng, vì sóng điện từ ảnh hưởng đến chất lượng giấc ngủ. Một phòng ngủ cân bằng là nền tảng cho sức khỏe và tinh thần tốt.', 'https://images.pexels.com/photos/6585760/pexels-photo-6585760.jpeg', 'bd849f7c-b613-11f0-83be-089798d71904', NULL, '2025-10-31 11:40:34', '2025-10-31 11:40:34'),
('bd8b4781-b613-11f0-83be-089798d71904', 'Tối ưu không gian nhỏ – bí quyết dành cho căn hộ hiện đại', 1, 'Với diện tích hạn chế, thiết kế thông minh là chìa khóa. Hãy chọn nội thất đa năng như giường có ngăn kéo, bàn gấp, hoặc ghế có thể cất gọn. Sử dụng tông màu sáng giúp không gian trông lớn hơn, đồng thời kết hợp gương hoặc cửa kính để mở rộng tầm nhìn. Ánh sáng tự nhiên luôn là yếu tố quan trọng giúp căn phòng thông thoáng. Ngoài ra, việc hạn chế đồ đạc không cần thiết và bố trí hợp lý giúp tạo cảm giác ngăn nắp, tiện nghi và hiện đại.', 'https://images.pexels.com/photos/157382/pexels-photo-157382.jpeg', 'bd84bc43-b613-11f0-83be-089798d71904', NULL, '2025-10-31 11:40:34', '2025-10-31 11:40:34'),
('bd8b48ac-b613-11f0-83be-089798d71904', 'Chất liệu gỗ trong thiết kế nội thất Việt Nam hiện đại', 1, 'Gỗ là vật liệu truyền thống nhưng vẫn luôn được yêu thích trong thiết kế nội thất hiện đại. Gỗ sồi, gỗ óc chó hoặc gỗ thông mang lại cảm giác ấm cúng, gần gũi. Khi kết hợp với kim loại hoặc kính, gỗ tạo nên sự cân bằng giữa truyền thống và hiện đại. Ngoài ra, việc xử lý bề mặt bằng dầu hoặc sơn mờ giúp giữ màu tự nhiên lâu hơn. Để không gian không bị nặng nề, nên kết hợp gỗ với tường trắng hoặc sàn sáng màu, giúp tổng thể nhẹ nhàng mà vẫn sang trọng.', 'https://images.pexels.com/photos/267569/pexels-photo-267569.jpeg', 'bd849f7c-b613-11f0-83be-089798d71904', NULL, '2025-10-31 11:40:34', '2025-10-31 11:40:34'),
('bd8b49d1-b613-11f0-83be-089798d71904', 'Đèn trang trí – điểm nhấn tinh tế trong không gian sống', 1, 'Một chiếc đèn đẹp không chỉ chiếu sáng mà còn là chi tiết trang trí đầy tinh tế. Đèn thả trần ở phòng ăn tạo nên bữa cơm ấm cúng, đèn cây trong góc đọc sách mang lại cảm giác thư giãn. Khi chọn đèn, hãy chú ý đến tông màu ánh sáng và kiểu dáng sao cho phù hợp phong cách tổng thể. Đèn vàng giúp không gian ấm cúng, đèn trắng cho cảm giác hiện đại, đèn RGB lại tạo nét phá cách. Đèn là linh hồn của không gian nếu biết đặt đúng chỗ.', 'https://images.pexels.com/photos/112811/pexels-photo-112811.jpeg', 'bd84bc43-b613-11f0-83be-089798d71904', NULL, '2025-10-31 11:40:34', '2025-10-31 11:40:34'),
('bd8b4aea-b613-11f0-83be-089798d71904', 'Tạo điểm nhấn với thảm trải sàn phong cách Bắc Âu', 1, 'Thảm trải sàn không chỉ giúp bảo vệ sàn nhà mà còn là yếu tố thẩm mỹ quan trọng. Phong cách Bắc Âu ưa chuộng thảm có họa tiết hình học hoặc đơn sắc nhẹ nhàng, chất liệu len hoặc cotton tự nhiên. Màu sắc nên hài hòa với sofa và rèm cửa. Thảm lớn có thể giúp phân chia không gian mở, tạo ranh giới giữa phòng khách và khu ăn uống. Để giữ thảm luôn mới, nên hút bụi thường xuyên và tránh phơi dưới nắng gắt. Một tấm thảm đẹp có thể thay đổi hoàn toàn diện mạo căn phòng.', 'https://images.pexels.com/photos/1457841/pexels-photo-1457841.jpeg', 'bd849f7c-b613-11f0-83be-089798d71904', NULL, '2025-10-31 11:40:34', '2025-10-31 11:40:34');
INSERT INTO `banner` (`id`, `tieude`, `mota`, `url`, `linksp`, `thutu`, `anhien`, `created_at`, `updated_at`) VALUES
(2, 'TRỞ THÀNH NGƯỜI CỘNG SỰ', 'Công ty TNHH Trang trí Nội thất và Xây dựng Vân Tây chuyên thiết kế và thi công các phòng vệ sắc có hình dạng trọn gói như cửa hàng, phòng làm việc/cửa hàng, các cửa hàng, Showroom với tiêu chí NHIỆT TÌNH - UY TÍN - HIỆU QUẢ', 'http://localhost:5000/uploads/banner/1763449517767-photo-1600210492486-724fe5c67fb0.jpg', '', 1, 1, '2025-11-18 06:52:17', '2025-11-18 07:08:01'),
(3, 'THIẾT KẾ NỘI THẤT HIỆN ĐẠI', 'Mang đến những không gian sống và làm việc hoàn hảo với phong cách thiết kế hiện đại, tối ưu công năng và thẩm mỹ cao. Đội ngũ kiến trúc sư giàu kinh nghiệm, sáng tạo và tư vấn miễn phí.', 'http://localhost:5000/uploads/banner/1763449734453-photo-1586023492125-27b2c045efd7.jpg', '', 2, 1, '2025-11-18 07:08:54', '2025-11-18 07:08:54'),
(4, 'THI CÔNG CHUYÊN NGHIỆP', 'Đội ngũ thợ lành nghề với nhiều năm kinh nghiệm, quy trình thi công chuyên nghiệp, đảm bảo tiến độ và chất lượng công trình theo đúng cam kết. Bảo hành dài hạn, hỗ trợ 24/7...', 'http://localhost:5000/uploads/banner/1763450236954-photo-1618221195710-dd6b41faaea6.jpg', '', 3, 1, '2025-11-18 07:17:16', '2025-11-18 07:17:16'),
(5, 'GIÁ TRỊ BỀN VỮNG - CHẤT LƯỢNG VƯỢT THỜI GIAN', 'Xây dựng mối quan hệ lâu dài với khách hàng thông qua chất lượng sản phẩm và dịch vụ tốt nhất. Cam kết tin cậy, trách nhiệm và phát triển bền vững cùng đối tác.', 'http://localhost:5000/uploads/banner/1763450263521-photo-1556912172-45b7abe8b7e1.jpg', '', 4, 1, '2025-11-18 07:17:43', '2025-11-18 07:17:43');
