INSERT INTO `san_pham` (`id`, `tensp`, `mota`, `ngay`, `trangthai`, `ratingTB`, `luotban`, `anhien`, `luotxem`, `thuonghieu_id`, `danhmuc_id`, `slug`, `thumbnail`, `code`, `created_at`, `updated_at`) VALUES
('bd1c8904-b613-11f0-83be-089798d71904', 'Sofa vải nỉ Bắc Âu', 'Thiết kế tối giản, chân gỗ tự nhiên, chất liệu vải nỉ cao cấp mang lại cảm giác êm ái cho phòng khách hiện đại.', '2025-10-31', 1, '0.0', 150, 1, 1020, 'bd116193-b613-11f0-83be-089798d71904', NULL, 'sofa-vai-ni-bac-au', 'https://images.pexels.com/photos/1866149/pexels-photo-1866149.jpeg', 'SP001', '2025-10-31 11:40:34', '2025-10-31 11:40:34'),
('bd1ca999-b613-11f0-83be-089798d71904', 'Bàn ăn gỗ sồi 6 ghế', 'Bàn ăn làm từ gỗ sồi tự nhiên, bề mặt phủ dầu chống trầy, phù hợp cho gia đình 4–6 người.', '2025-10-31', 1, '0.0', 90, 1, 860, 'bd117f7b-b613-11f0-83be-089798d71904', 'bd0f46ea-b613-11f0-83be-089798d71904', 'ban-an-go-soi-6-ghe', 'https://images.pexels.com/photos/5695871/pexels-photo-5695871.jpeg', 'SP002', '2025-10-31 11:40:34', '2025-10-31 11:40:34'),
('bd1cac5f-b613-11f0-83be-089798d71904', 'Tủ quần áo cánh trượt Hòa Phát', 'Tủ 3 ngăn lớn, thiết kế trượt tiết kiệm không gian, màu trắng sữa sang trọng.', '2025-10-31', 1, '0.0', 120, 1, 930, NULL, 'bd0f4845-b613-11f0-83be-089798d71904', 'tu-quan-ao-canh-truot-hoa-phat', 'https://images.pexels.com/photos/6585766/pexels-photo-6585766.jpeg', 'SP003', '2025-10-31 11:40:34', '2025-10-31 11:40:34'),
('bd1caf1b-b613-11f0-83be-089798d71904', 'Kệ trang trí kim loại 5 tầng', 'Khung sắt sơn tĩnh điện, kệ gỗ công nghiệp MDF, chịu lực tốt, phù hợp phòng khách hoặc văn phòng.', '2025-10-31', 1, '0.0', 85, 1, 740, 'bd11818a-b613-11f0-83be-089798d71904', 'bd0f48d3-b613-11f0-83be-089798d71904', 'ke-trang-tri-kim-loai-5-tang', 'https://images.pexels.com/photos/271795/pexels-photo-271795.jpeg', 'SP004', '2025-10-31 11:40:34', '2025-10-31 11:40:34'),
('bd1cb10a-b613-11f0-83be-089798d71904', 'Đèn trần 3 vòng LED hiện đại', 'Đèn trần LED cao cấp, thiết kế vòng tròn xoắn tinh tế, ánh sáng vàng ấm, tiết kiệm điện năng.', '2025-10-31', 1, '0.0', 130, 1, 1240, 'bd118250-b613-11f0-83be-089798d71904', 'bd0f4a22-b613-11f0-83be-089798d71904', 'den-tran-3-vong-led-hien-dai', 'https://images.pexels.com/photos/6585757/pexels-photo-6585757.jpeg', 'SP005', '2025-10-31 11:40:34', '2025-10-31 11:40:34'),
('bd1cb7e9-b613-11f0-83be-089798d71904', 'Giường ngủ gỗ sồi Bắc Âu', 'Giường gỗ sồi tự nhiên, khung chắc chắn, đầu giường bo tròn an toàn, phù hợp không gian tối giản.', '2025-10-31', 1, '0.0', 175, 1, 1450, NULL, 'bd0f4ad1-b613-11f0-83be-089798d71904', 'giuong-ngu-go-soi-bac-au', 'https://images.pexels.com/photos/6585760/pexels-photo-6585760.jpeg', 'SP006', '2025-10-31 11:40:34', '2025-10-31 11:40:34'),
