('bd4e16a5-b613-11f0-83be-089798d71904', 'Ghế training gấp gọn IKEA FlexFold', 'Ghế nhựa ABS cao cấp, khung sắt mạ kẽm, dễ xếp chồng, nhẹ và tiện dụng.', '2025-10-31', 1, '0.0', 150, 1, 910, 'bd116193-b613-11f0-83be-089798d71904', NULL, 'ghe-training-gap-gon-ikea-flexfold', 'https://images.pexels.com/photos/813694/pexels-photo-813694.jpeg', 'SP076', '2025-10-31 11:40:34', '2025-10-31 11:40:34'),
('bd4e17b8-b613-11f0-83be-089798d71904', 'Ghế nhân viên LuxHome Junior Mesh', 'Màu xám trung tính, tựa lưng lưới, chân xoay êm ái, phù hợp không gian làm việc trẻ trung.', '2025-10-31', 1, '0.0', 200, 1, 990, 'bd118250-b613-11f0-83be-089798d71904', NULL, 'ghe-nhan-vien-luxhome-junior-mesh', 'https://images.pexels.com/photos/374074/pexels-photo-374074.jpeg', 'SP077', '2025-10-31 11:40:34', '2025-10-31 11:40:34'),
('bd4e18a9-b613-11f0-83be-089798d71904', 'Ghế phòng chờ Hòa Phát CH-05 3 chỗ', 'Ghế băng 3 chỗ, khung thép sơn tĩnh điện, đệm nỉ êm ái, phù hợp sảnh lễ tân.', '2025-10-31', 1, '0.0', 180, 1, 940, NULL, NULL, 'ghe-phong-cho-hoa-phat-ch05', 'https://images.pexels.com/photos/1866149/pexels-photo-1866149.jpeg', 'SP078', '2025-10-31 11:40:34', '2025-10-31 11:40:34'),
('bd4e19a4-b613-11f0-83be-089798d71904', 'Bàn làm việc gỗ óc chó AConcept', 'Mặt bàn veneer óc chó cao cấp, chân thép đen, tông màu sang trọng, thiết kế thanh lịch.', '2025-10-31', 1, '0.0', 150, 1, 870, 'bd117f7b-b613-11f0-83be-089798d71904', 'bd0f46ea-b613-11f0-83be-089798d71904', 'ban-lam-viec-go-oc-cho-aconcept', 'https://images.pexels.com/photos/267569/pexels-photo-267569.jpeg', 'SP079', '2025-10-31 11:40:34', '2025-10-31 11:40:34'),
('bd4e1ab2-b613-11f0-83be-089798d71904', 'Bàn chữ U LuxHome Executive', 'Bàn giám đốc chữ U, tích hợp tủ phụ, mặt laminate vân gỗ sồi, tạo cảm giác uy nghi.', '2025-10-31', 1, '0.0', 190, 1, 1090, 'bd118250-b613-11f0-83be-089798d71904', 'bd0f46ea-b613-11f0-83be-089798d71904', 'ban-chu-u-luxhome-executive', 'https://images.pexels.com/photos/5695871/pexels-photo-5695871.jpeg', 'SP080', '2025-10-31 11:40:34', '2025-10-31 11:40:34'),
('bd4e1bc0-b613-11f0-83be-089798d71904', 'Bàn họp dài Gotrust 3m 10 người', 'Mặt gỗ MFC dày 36mm, chân sắt hộp, thiết kế liền khối, sang trọng cho không gian hội nghị.', '2025-10-31', 1, '0.0', 230, 1, 970, NULL, 'bd0f46ea-b613-11f0-83be-089798d71904', 'ban-hop-dai-gotrust-3m', 'https://images.pexels.com/photos/276528/pexels-photo-276528.jpeg', 'SP081', '2025-10-31 11:40:34', '2025-10-31 11:40:34'),
('bd4e1d4c-b613-11f0-83be-089798d71904', 'Bàn cụm 4 chỗ IKEA Connect', 'Bàn modular có vách ngăn, mặt phủ melamine, thích hợp mô hình coworking.', '2025-10-31', 1, '0.0', 170, 1, 860, 'bd116193-b613-11f0-83be-089798d71904', 'bd0f46ea-b613-11f0-83be-089798d71904', 'ban-cum-4-cho-ikea-connect', 'https://images.pexels.com/photos/5695871/pexels-photo-5695871.jpeg', 'SP082', '2025-10-31 11:40:34', '2025-10-31 11:40:34'),
('bd4e1e90-b613-11f0-83be-089798d71904', 'Bàn tiếp khách VHome Coffee Table', 'Mặt kính cường lực, chân gỗ sồi, thiết kế đơn giản, phù hợp khu vực lễ tân.', '2025-10-31', 1, '0.0', 150, 1, 840, 'bd11818a-b613-11f0-83be-089798d71904', 'bd0f46ea-b613-11f0-83be-089798d71904', 'ban-tiep-khach-vhome-coffee', 'https://images.pexels.com/photos/276528/pexels-photo-276528.jpeg', 'SP083', '2025-10-31 11:40:34', '2025-10-31 11:40:34'),
('bd4e1f99-b613-11f0-83be-089798d71904', 'Bàn giám đốc đôi LuxHome Master Desk', 'Bàn đôi kết hợp tủ tài liệu, mặt veneer walnut, khung sắt đen, sang trọng.', '2025-10-31', 1, '0.0', 100, 1, 810, 'bd118250-b613-11f0-83be-089798d71904', 'bd0f46ea-b613-11f0-83be-089798d71904', 'ban-giam-doc-doi-luxhome-master', 'https://images.pexels.com/photos/267569/pexels-photo-267569.jpeg', 'SP084', '2025-10-31 11:40:34', '2025-10-31 11:40:34'),
('bd4e2095-b613-11f0-83be-089798d71904', 'Bàn làm việc mini Hòa Phát Simple', 'Mặt bàn 1m, chân sắt gấp gọn, phù hợp văn phòng nhỏ hoặc làm việc tại nhà.', '2025-10-31', 1, '0.0', 210, 1, 970, NULL, 'bd0f46ea-b613-11f0-83be-089798d71904', 'ban-lam-viec-mini-hoa-phat-simple', 'https://images.pexels.com/photos/276528/pexels-photo-276528.jpeg', 'SP085', '2025-10-31 11:40:34', '2025-10-31 11:40:34'),
('bd4e2178-b613-11f0-83be-089798d71904', 'Tủ hồ sơ 3 buồng LuxHome', 'Tủ lớn, cửa kính cường lực, màu vân gỗ nâu sáng, lưu trữ tài liệu khoa học.', '2025-10-31', 1, '0.0', 190, 1, 880, 'bd118250-b613-11f0-83be-089798d71904', 'bd0f4845-b613-11f0-83be-089798d71904', 'tu-ho-so-3-buong-luxhome', 'https://images.pexels.com/photos/7061412/pexels-photo-7061412.jpeg', 'SP086', '2025-10-31 11:40:34', '2025-10-31 11:40:34'),
('bd4e2286-b613-11f0-83be-089798d71904', 'Tủ di động IKEA UnderDesk Drawer', 'Tủ nhỏ đặt dưới bàn, 3 ngăn kéo, bánh xe dễ di chuyển, màu trắng thanh lịch.', '2025-10-31', 1, '0.0', 120, 1, 780, 'bd116193-b613-11f0-83be-089798d71904', 'bd0f4845-b613-11f0-83be-089798d71904', 'tu-di-dong-ikea-underdesk', 'https://images.pexels.com/photos/7061413/pexels-photo-7061413.jpeg', 'SP087', '2025-10-31 11:40:34', '2025-10-31 11:40:34'),
('bd4e2388-b613-11f0-83be-089798d71904', 'Tủ hồ sơ gỗ sồi Gotrust Classic', 'Tủ 4 tầng, gỗ sồi tự nhiên, màu vàng sáng, phù hợp không gian giám đốc.', '2025-10-31', 1, '0.0', 110, 1, 770, NULL, 'bd0f4845-b613-11f0-83be-089798d71904', 'tu-ho-so-go-soi-gotrust-classic', 'https://images.pexels.com/photos/7061412/pexels-photo-7061412.jpeg', 'SP088', '2025-10-31 11:40:34', '2025-10-31 11:40:34'),
('bd4e2479-b613-11f0-83be-089798d71904', 'Tủ sắt văn phòng Hòa Phát TL-Metal', 'Tủ sắt sơn tĩnh điện, 2 tầng, cửa trượt, chịu lực tốt, bền bỉ với thời gian.', '2025-10-31', 1, '0.0', 170, 1, 880, NULL, 'bd0f4845-b613-11f0-83be-089798d71904', 'tu-sat-van-phong-hoa-phat-tlmetal', 'https://images.pexels.com/photos/7061412/pexels-photo-7061412.jpeg', 'SP089', '2025-10-31 11:40:34', '2025-10-31 11:40:34'),
('bd4e256f-b613-11f0-83be-089798d71904', 'Kệ góc trang trí AConcept Elegant', 'Thiết kế hình tam giác, tiết kiệm không gian, phù hợp góc phòng hoặc hành lang.', '2025-10-31', 1, '0.0', 140, 1, 790, 'bd117f7b-b613-11f0-83be-089798d71904', 'bd0f48d3-b613-11f0-83be-089798d71904', 'ke-goc-trang-tri-aconcept-elegant', 'https://images.pexels.com/photos/271795/pexels-photo-271795.jpeg', 'SP090', '2025-10-31 11:40:34', '2025-10-31 11:40:34'),
('bd4e268f-b613-11f0-83be-089798d71904', 'Kệ gỗ 5 tầng LuxHome Stand', 'Kệ đứng 5 tầng, gỗ MDF phủ laminate, tông nâu nhạt, lưu trữ hồ sơ, cây cảnh nhỏ.', '2025-10-31', 1, '0.0', 100, 1, 810, 'bd118250-b613-11f0-83be-089798d71904', 'bd0f48d3-b613-11f0-83be-089798d71904', 'ke-go-5-tang-luxhome-stand', 'https://images.pexels.com/photos/271795/pexels-photo-271795.jpeg', 'SP091', '2025-10-31 11:40:34', '2025-10-31 11:40:34'),
('bd4e279c-b613-11f0-83be-089798d71904', 'Đèn sàn văn phòng IKEA TallLamp', 'Đèn sàn kiểu dáng thanh mảnh, ánh sáng vàng, phù hợp góc làm việc hoặc đọc sách.', '2025-10-31', 1, '0.0', 170, 1, 850, 'bd116193-b613-11f0-83be-089798d71904', 'bd0f4a22-b613-11f0-83be-089798d71904', 'den-san-van-phong-ikea-talllamp', 'https://images.pexels.com/photos/271635/pexels-photo-271635.jpeg', 'SP092', '2025-10-31 11:40:34', '2025-10-31 11:40:34'),
('bd4e28ba-b613-11f0-83be-089798d71904', 'Đèn bàn LED LuxHome SmartEye', 'Cảm ứng thông minh, điều chỉnh ánh sáng tự nhiên, tiết kiệm năng lượng.', '2025-10-31', 1, '0.0', 140, 1, 780, 'bd118250-b613-11f0-83be-089798d71904', 'bd0f4a22-b613-11f0-83be-089798d71904', 'den-ban-led-luxhome-smarteye', 'https://images.pexels.com/photos/619419/pexels-photo-619419.jpeg', 'SP093', '2025-10-31 11:40:34', '2025-10-31 11:40:34'),
('bd4e29ca-b613-11f0-83be-089798d71904', 'Đèn ốp trần Gotrust Halo LED', 'Thiết kế viền mảnh, ánh sáng dịu nhẹ, phù hợp phòng họp hoặc không gian chung.', '2025-10-31', 1, '0.0', 180, 1, 850, NULL, 'bd0f4a22-b613-11f0-83be-089798d71904', 'den-op-tran-gotrust-halo-led', 'https://images.pexels.com/photos/112811/pexels-photo-112811.jpeg', 'SP094', '2025-10-31 11:40:34', '2025-10-31 11:40:34'),
('bd4e2abe-b613-11f0-83be-089798d71904', 'Đèn chùm LuxHome Elegant Chandelier', 'Đèn chùm pha lê, ánh sáng trắng, tạo điểm nhấn sang trọng cho văn phòng cao cấp.', '2025-10-31', 1, '0.0', 90, 1, 910, 'bd118250-b613-11f0-83be-089798d71904', 'bd0f4a22-b613-11f0-83be-089798d71904', 'den-chum-luxhome-elegant-chandelier', 'https://images.pexels.com/photos/1966626/pexels-photo-1966626.jpeg', 'SP095', '2025-10-31 11:40:34', '2025-10-31 11:40:34'),
('bd4e2c6b-b613-11f0-83be-089798d71904', 'Đèn bàn nhỏ VHome BrightMini', 'Đèn mini ánh sáng trắng, thiết kế gấp gọn, tiện mang theo khi làm việc linh hoạt.', '2025-10-31', 1, '0.0', 150, 1, 890, 'bd11818a-b613-11f0-83be-089798d71904', 'bd0f4a22-b613-11f0-83be-089798d71904', 'den-ban-nho-vhome-brightmini', 'https://images.pexels.com/photos/619419/pexels-photo-619419.jpeg', 'SP096', '2025-10-31 11:40:34', '2025-10-31 11:40:34');
